Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (1,1,'자유','첫 번째 자유 게시글','안녕하세요! 뜨개질 시작한 지 얼마 안 됐어요 😊',2,null,null,to_timestamp('26/05/30 14:04:08.375000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/05/30 14:34:25.956000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (2,1,'질문','코바늘 기초 질문이요!','한길긴뜨기랑 긴뜨기 차이가 뭔가요?',0,null,null,to_timestamp('26/05/30 14:04:08.386000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/05/30 14:04:08.386000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (7,1,'자유','오늘 카페에서 뜨개질 했어요!','부평 스타벅스에서 3시간 뜨개질 ㅎㅎ',0,null,null,to_timestamp('26/05/30 14:59:47.683000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/05/30 14:59:47.683000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (11,1,'자유','첫 작품 완성했어요!!','드디어 곰돌이 인형 완성 ㅠㅠ 너무 뿌듯해요',0,null,null,to_timestamp('26/05/30 14:59:47.743000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/05/30 14:59:47.743000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (12,1,'질문','실 엉킨거 푸는 팁 있나요?','뜨다가 실이 너무 엉켜서 힘드네요 ㅠㅠ',0,null,null,to_timestamp('26/05/30 14:59:47.747000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/05/30 14:59:47.747000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (41,43,'질문',null,'실 정리 어떻게 하세요? 저는 집에 실이 너무 많아져서 수납 방법 고민 중이에요. 바구니에 색깔별로 넣어두는데 자꾸 엉켜서 스트레스받아요 😭',0,null,null,to_timestamp('26/06/04 15:48:57.407000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:48:57.407000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (42,43,'모여떠요',null,'홍대 근처에서 같이 뜨실 분 구해요! 매주 토요일 오후 2시에 홍대역 근처 카페에서 모이고 있어요. 초보도 환영이에요 🧶 관심 있으신 분은 채팅방 들어와주세요!',0,null,null,to_timestamp('26/06/04 15:49:10.176000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:49:10.176000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (43,51,'자유',null,'카페에서 뜨개질 하다가 옆에 분이 말 걸어주셨는데 같이 2시간 동안 뜨다가 헤어졌어요 ㅋㅋㅋ 뜨개질이 이렇게 사교적인 취미인 줄 몰랐네요 🧶',0,null,null,to_timestamp('26/06/04 15:50:25.589000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:50:25.589000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (45,47,'모여떠요',null,'26.06.14(토) 강남 뜨개 모임 열어요! 
도산공원 근처 카페에서 모일 예정이에요. 
대바늘/코바늘 상관없이 같이 뜨실 분이면 누구든 환영해요 😊

-초대 코드-
7MSRSKH6',0,null,null,to_timestamp('26/06/04 15:59:49.827000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:00:29.171000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (47,49,'떠주세요',null,'아기 돌 선물로 뜨개 인형 부탁드려요! 곰돌이나 토끼 모양으로 부탁드리고 싶은데 재료비는 드릴게요. 혹시 가능하신 분 계시면 댓글 달아주세요 🐻',0,null,null,to_timestamp('26/06/04 16:02:49.164000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:02:49.164000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (48,49,'자유',null,'오늘 너무 덥더라구요. 벌써 여름인가봐요 켁;; ',0,null,null,to_timestamp('26/06/04 16:04:29.833000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:04:29.833000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (50,50,'질문',null,'도안 보는 법 잘 모르겠어요 ㅠㅠ 기호들이 너무 많아서 뭐가 뭔지 헷갈려요. 코바늘 기초 기호 설명해주실 수 있나요? 아니면 좋은 유튜브 채널 추천해주셔도 감사해요!',0,null,null,to_timestamp('26/06/04 16:08:22.666000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:08:22.666000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (51,50,'자유',null,'끄악... 손목이 너덜너더.. 하지만 스와치들 보면 마음이 몽글몽글해지는거 저만 그런거 아니죠? ㅎㅎ',0,null,null,to_timestamp('26/06/04 16:14:09.041000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:14:09.041000000','RR/MM/DD HH24:MI:SSXFF'));
