Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (28,41,'자유',null,'뉴 도안들 ...조만간 업로드 예정..',0,null,null,to_timestamp('26/06/02 15:52:48.286000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/02 15:52:48.286000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (30,41,'작품자랑','손 부숴지는줄 알았습니다. 역작이에요.','정말 오래 걸렸던... 저의 첫 코바늘 가디건 입니다!!
주머니도 만들고 엄청 만족 스러워요.
안감을 달아주면 더 멋질 거 같은데 집에 재봉틀이 없어서 거기까진.. 또르륵...',0,null,null,to_timestamp('26/06/02 17:03:44.649000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/02 17:03:44.649000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (33,21,'작품자랑','고양이 모자 뜨기ㅋㅋ','고양이 귀가 들어갈 구멍도 만들어줬어요. 표정은 무섭지만 모자도 잘쓰고 있죠. ^^
이름은 하루랍니다.
그리고 이거 찍고 바로 벗어서 던져버렸네요 효묘 ^^... ',0,null,null,to_timestamp('26/06/04 14:31:26.563000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 14:58:03.583000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (46,47,'질문',null,'처음 시작하는데 코바늘이랑 대바늘 중에 뭐가 더 쉬운가요? 주변에서 코바늘이 쉽다고 하는데 대바늘이 더 예쁜 것 같아서 고민이에요.',0,null,null,to_timestamp('26/06/04 16:00:59.676000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:00:59.676000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (40,2,'자유',null,'오늘 드디어 첫 코바늘 완성했어요!! 고양이 모자인데 생각보다 너무 잘 됐어서 기분이 너무 좋아요 🐱 다음엔 강아지 스웨터 도전해볼 예정이에요!',0,null,null,to_timestamp('26/06/04 15:47:39.014000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:47:39.014000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (44,52,'자유',null,'새로운 프로필 이미지예요.
친구들이 너는 왜 맨날 목도리만 뜨녜요.
하지만 목도리가 제일 재미있는걸 어찌하나요 ',0,null,null,to_timestamp('26/06/04 15:52:37.063000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:52:37.063000000','RR/MM/DD HH24:MI:SSXFF'));
Insert into MOYEODDUGI.POSTS (POST_ID,USER_ID,BOARD_TYPE,TITLE,CONTENT,VIEW_COUNT,GATHER_STATUS,GATHER_COUNT,CREATED_AT,UPDATED_AT) values (49,45,'떠드려요',null,'대바늘 목도리 떠드려요! 재료비 + 소정의 수고비 받아요. 색상은 원하시는 걸로 맞춰드릴 수 있어요. 완성 기간은 1~2주 정도 예상돼요. 관심 있으신 분은 댓글이나 채팅으로 연락주세요 🧶',0,null,null,to_timestamp('26/06/04 16:07:37.762000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:07:37.762000000','RR/MM/DD HH24:MI:SSXFF'));
